 p=argparse.ArgumentParser();p.add_argument('--scene',type=Path,required=True);p.add_argument('--scaffold-report',type=Path,required=True);p.add_argument('--mask',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args(sys.argv[sys.argv.index('--')+1:]);r=json.loads(a.scaffold_report.read_text());mask=json.loads(a.mask.read_text());checks={};checks['saved_scene_sha']=sha(a.scene)==r['scene']['sha256'];bpy.ops.wm.open_mainfile(filepath=str(a.scene.resolve()));source=bpy.data.objects['GENERATED ORIGINAL reference DO NOT DELETE'];high=bpy.data.objects['DONOR exact rear-nape UNFITTED reference'];seed=bpy.data.objects['EDITABLE reduction SEED UNFITTED not quad-retopo']
